/* ==========================================================================
   ProxCenter — 中文词条（源语言）

   这个文件是**词条的权威来源**：`MessageKey` 由它的键推导而来，英文词条
   必须与之对得上（`en.ts` 用 Partial<Record<MessageKey, string>> 约束），
   多写一个不存在的键会编译报错，漏翻则自动回退到这里的文案。

   键的命名：`<区域>.<含义>`，区域按界面位置划分而不是按页面文件 ——
   同一条文案被多处引用时（如「取消」），只保留一份。
   ========================================================================== */

