  /* ------------------------------------------------------------ 常见问题 */
  'faq.q1': '需要把 Proxmox 暴露到公网吗？',
  'faq.a1': '不需要。面板在内网通过 Proxmox API（默认 8006）访问集群，只有面板自身需要对外提供访问入口。',
  'faq.q2': '为什么浏览器控制台还需要额外填一个 Proxmox 账号？',
  'faq.a2': 'Proxmox 不允许 API Token 调用 vncproxy，控制台只认用户名密码换取的 ticket。该功能可选，不填不影响其它功能。',
  'faq.q3': 'SSL 证书「自动续期」是怎么工作的？',
  'faq.a3': '以腾讯云免费 DV 证书为例：证书有效期 90 天，面板会按你设定的天数（默认到期前 15 天）自动提交续期申请，等 CA 签发成功后自动下载并重新部署到目标机器，最后执行你配置的重载命令（如 nginx -s reload）。',
  'faq.q4': '飞书机器人需要公网回调吗？会不会被人乱操作？',
  'faq.a4': '需要：机器人通过飞书开放平台的事件回调访问面板，回调地址必须能被飞书访问到（内网部署可用反向代理或内网穿透）。安全上做了两层限制：一是必须配置群会话或用户白名单，名单外的消息一律拒绝；二是关机、重启、回滚这类危险操作会先弹确认卡片，点确认才执行，全过程写入审计日志。',
